#pragma once

#include "gfx/Color.h"

#include <cstddef>

class gfxSprite;


/// The original art has colors for 4 teams. Until there is art for more,
/// the colors of teams 5-8 are generated by shifting the hue of one of the original 4.
namespace team_colors {

/// How many team colors the original art has.
constexpr size_t ORIGINAL_COUNT = 4;

/// The original team whose colors a generated team is based on.
size_t sourceTeam(size_t team);

/// Turns a color of `sourceTeam(team)` into the matching color of `team`.
/// Original teams, and colors without a hue (black, white, gray), are returned unchanged.
RGB colorFor(RGB sourceColor, size_t team);

enum class Axis { X, Y };

/// Extends a sprite sheet that has a variant for each original team, laid out along `axis`,
/// `stride` pixels apart, with a variant for every team up to MAX_TEAMS.
/// `firstVariant` is the number of variants before the first team one (eg. an uncolored one).
/// Sheets that don't have exactly ORIGINAL_COUNT team variants are left unchanged.
/// Returns whether the sheet was extended.
bool extendSheet(gfxSprite& sprite, Axis axis, int stride, int firstVariant = 0);

} // namespace team_colors
